(() => {
  'use strict';
  const config = window.MGD_CMS_CONFIG || {};
  const client = window.supabase && config.url && config.key ? window.supabase.createClient(config.url, config.key) : null;
  const $ = (s) => document.querySelector(s);
  const state = { section: 'slides', records: [], selected: null, mobilePreview: false };
  const labels = { slides: 'Ana sayfa slider', news: 'Haberler ve duyurular' };
  const status = (message, error = false) => { const el = $('#panel-status'); el.textContent = message; el.className = error ? 'error' : ''; };
  const escape = (value) => String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
  const table = () => state.section === 'slides' ? 'mgd_slides' : 'mgd_news';
  const emptyRecord = () => state.section === 'slides' ? { title: '', summary: '', button_label: 'Derneğimizi Tanıyın', button_url: '#kurumsal', image_url: '', mobile_image_url: '', sort_order: 0, status: 'draft' } : { title: '', summary: '', body: '', category: 'Haber', image_url: '', published_at: new Date().toISOString().slice(0,10), sort_order: 0, status: 'draft' };
  function setMode() { document.querySelectorAll('.slider-only').forEach((el) => { el.hidden = state.section !== 'slides'; }); document.querySelectorAll('.news-only').forEach((el) => { el.hidden = state.section === 'slides'; }); $('#title-help').textContent = state.section === 'slides' ? 'En fazla 2 satır. Satır sonu için Enter kullanın.' : 'Haber başlığını yazın.'; $('#cover-label').firstChild.textContent = state.section === 'slides' ? 'Masaüstü görseli / slider kapağı' : 'Haber kapağı'; $('#image-help').textContent = state.section === 'slides' ? 'Slider: 1920 × 900 px. JPEG, PNG veya WEBP; en fazla 5 MB.' : 'Önerilen: 1600 × 900 px. JPEG, PNG veya WEBP; en fazla 5 MB.'; }
  async function load() { if (!client) { status('CMS bağlantısı henüz yapılandırılmadı.', true); return; } const { data: { user } } = await client.auth.getUser(); if (!user) return showLogin(); $('#account').textContent = user.email || 'Yetkili kullanıcı'; $('#login').hidden = true; $('#panel').hidden = false; await reload(); }
  async function reload() { const { data, error } = await client.from(table()).select('*').order('sort_order', { ascending: true }).order('created_at', { ascending: false }); if (error) return status(error.message, true); state.records = data || []; renderList(); if (state.selected) { const fresh = state.records.find((r) => r.id === state.selected.id); state.selected = fresh || null; } if (state.selected) fill(state.selected); }
  function renderList() { const q = $('#filter').value.trim().toLocaleLowerCase('tr'); const rows = state.records.filter((r) => !q || `${r.title} ${r.summary}`.toLocaleLowerCase('tr').includes(q)); $('#list').innerHTML = rows.length ? rows.map((r) => `<button class="record ${state.selected?.id === r.id ? 'active' : ''}" data-id="${r.id}"><b>${escape(r.title || 'Başlıksız içerik')}</b><small>${escape(r.status === 'published' ? 'Yayında' : 'Taslak')} · ${escape(state.section === 'slides' ? 'Slider' : r.category)}</small></button>`).join('') : '<p id="empty">Henüz içerik yok.</p>'; $('#list').querySelectorAll('[data-id]').forEach((el) => el.onclick = () => { state.selected = state.records.find((r) => r.id === el.dataset.id); fill(state.selected); renderList(); }); }
  function fill(r) { $('#empty').hidden = true; $('#content-form').hidden = false; $('#form-title').textContent = r.id ? 'İçerik düzenle' : 'Yeni içerik'; $('#record-state').textContent = r.status === 'published' ? 'YAYINDA' : 'TASLAK'; $('#title').value = r.title || ''; $('#summary').value = r.summary || ''; $('#button-label').value = r.button_label || ''; $('#button-url').value = r.button_url || ''; $('#sort-order').value = r.sort_order ?? 0; $('#focus-x').value = r.focus_x ?? 50; $('#category').value = r.category || 'Haber'; $('#published-at').value = r.published_at || ''; $('#body').value = r.body || ''; $('#status').value = r.status || 'draft'; $('#preview-image').src = r.image_url || ''; updatePreview(); setMode(); }
  function updatePreview() { $('#preview').classList.toggle('mobile', state.mobilePreview); $('#preview-image').src = $('#image').dataset.url || (state.selected?.image_url || ''); $('#preview-title').textContent = $('#title').value; $('#preview-summary').textContent = $('#summary').value; $('#preview-button').textContent = state.section === 'slides' ? ($('#button-label').value || 'Derneğimizi Tanıyın') : ($('#category').value || 'Haber'); }
  async function upload(file) { if (!file) return ''; if (file.size > 5 * 1024 * 1024) throw Error('Görsel en fazla 5 MB olabilir.'); if (!['image/jpeg','image/png','image/webp'].includes(file.type)) throw Error('JPG, PNG veya WEBP seçin.'); const path = `${state.section}/${crypto.randomUUID()}-${file.name.replace(/[^a-z0-9._-]/gi,'-')}`; const { error } = await client.storage.from('mgd-media').upload(path, file, { upsert: false, contentType: file.type }); if (error) throw error; const { data } = client.storage.from('mgd-media').getPublicUrl(path); return data.publicUrl; }
  async function save(event) { event.preventDefault(); const old = state.selected || {}; const payload = state.section === 'slides' ? { title: $('#title').value.trim(), summary: $('#summary').value.trim(), button_label: $('#button-label').value.trim(), button_url: $('#button-url').value.trim(), sort_order: Number($('#sort-order').value || 0), status: $('#status').value, image_url: old.image_url || '', mobile_image_url: old.mobile_image_url || '' } : { title: $('#title').value.trim(), summary: $('#summary').value.trim(), body: $('#body').value.trim(), category: $('#category').value, published_at: $('#published-at').value || null, sort_order: Number($('#sort-order').value || 0), status: $('#status').value, image_url: old.image_url || '' }; if (!payload.title) return status('Başlık zorunludur.', true); try { const desktop = await upload($('#image').files[0]); if (desktop) payload.image_url = desktop; if (state.section === 'slides') { const mobile = await upload($('#mobile-image').files[0]); if (mobile) payload.mobile_image_url = mobile; if ($('#clear-mobile').checked) payload.mobile_image_url = ''; } status('Kaydediliyor…'); const result = old.id ? await client.from(table()).update(payload).eq('id', old.id) : await client.from(table()).insert(payload); if (result.error) throw result.error; status('İçerik kaydedildi.'); $('#image').value = ''; $('#mobile-image').value = ''; await reload(); } catch (error) { status(error.message || 'Kaydedilemedi.', true); } }
  async function remove() { if (!state.selected?.id || !confirm('Bu içerik silinsin mi?')) return; const { error } = await client.from(table()).delete().eq('id', state.selected.id); if (error) return status(error.message, true); state.selected = null; $('#content-form').hidden = true; $('#empty').hidden = false; await reload(); status('İçerik silindi.'); }
  function showLogin() { $('#login').hidden = false; $('#panel').hidden = true; }
  $('#login-form').onsubmit = async (event) => { event.preventDefault(); if (!client) return $('#login-status').textContent = 'CMS bağlantısı yapılandırılmadı.'; const button = $('#login-button'); button.disabled = true; const { error } = await client.auth.signInWithPassword({ email: $('#email').value.trim(), password: $('#password').value }); button.disabled = false; if (error) { $('#login-status').textContent = 'E-posta veya şifre hatalı.'; return; } $('#login-status').textContent = ''; await load(); };
  $('#logout').onclick = async () => { await client.auth.signOut(); showLogin(); };
  document.querySelectorAll('[data-section]').forEach((button) => button.onclick = async () => { state.section = button.dataset.section; state.selected = null; document.querySelectorAll('[data-section]').forEach((b) => b.classList.toggle('active', b === button)); $('#heading').textContent = labels[state.section]; $('#content-form').hidden = true; $('#empty').hidden = false; setMode(); await reload(); });
  $('#add').onclick = () => { state.selected = emptyRecord(); fill(state.selected); renderList(); };
  $('#save').onclick = save; $('#delete').onclick = remove; $('#filter').oninput = renderList; $('#preview-mode').onclick = () => { state.mobilePreview = !state.mobilePreview; $('#preview-mode').textContent = state.mobilePreview ? 'Masaüstü görünümü' : 'Mobil görünüm'; updatePreview(); }; ['title','summary','button-label','category'].forEach((id) => $(`#${id}`).addEventListener('input', updatePreview));
  $('#image').onchange = () => { const f = $('#image').files[0]; if (f) $('#image').dataset.url = URL.createObjectURL(f); updatePreview(); }; load();
})();

